        "text": "Вор Лютобор атакует стражника кинжалом. Целевое число: значение Ловкости + модификатор навыка «Одноручное оружие» + вложенное значение навыка (если есть) − Броня стражника (15). Бросок к100 — «22», дубль и успех. Он наносит обычный урон (1к4 + 7 = 9), а также Сказитель бросает к10; выпадает «3» — «Выбивание оружия». Стражник должен пройти Избавление Силы. Выпадает 55 — провал. Меч стражника падает на землю."
