        "text": "Кто платит: верующие (по желанию, но часто под давлением общины). Размер: 10% от доходов (или фиксированная сумма). Как платится: при посещении храма, обычно раз в месяц. В некоторых княжествах десятина обязательна для всех. Последствия неуплаты: общественное порицание, отказ в обрядах, а в фанатичных общинах — штраф."
