        "text": "Внешность:\nЛюди Пармы разнообразны, как сама Явь. Северяне — высокие, светловолосые, с серыми или голубыми глазами. Южане — коренастые, смуглые, с тёмными волосами и глазами. Лесные жители часто носят одежду из кожи и меха, городские — льняные рубахи и суконные кафтаны."
