        "kind": "paragraph",
        "text": "Внешность:\nВысокие (до 2 м), с яркой, неестественной кожей — от синеватой до фиолетовой или серой. Глаза — ярко-красные, жёлтые или белые, светятся в темноте. На голове — небольшие рога. Ноги заканчиваются копытами."
