        "kind": "paragraph",
        "text": "Теневая Связь. Активное умение, 1 раз в день. На 1 минуту вы получаете преимущество (+10) на проверки Запугивания и можете видеть в магической тьме. После окончания эффекта вы получаете 1 уровень состояния Изнеможение."
