        "kind": "paragraph",
        "text": "Внешность:\nВысокие (2,2–2,7 м), мощные, с покрытой чешуёй кожей. Цвет чешуи зависит от стихии: огненно-красные, ледяные белые, чёрные, ядовито-зелёные, серебряные, синие (грозовые). На голове — рога (разной формы). Глаза — вертикальные зрачки."
