        "text": "Дыхательное Оружие. Активное умение (действие в бою). Вы выдыхаете энергию в конусе 4 сажени (близь). Все существа в зоне должны пройти Избавление Ловкости (уклонение). Сложность = 10 + модификатор Силы. Урон: 2к6 выбранного типа (половина при успехе). Восстанавливается после продолжительного отдыха. Урон растёт: 3к6 (ур.6), 4к6 (ур.11), 5к6 (ур.16)."
