        "kind": "paragraph",
        "text": "Они дети богов, посланные в мир с благой целью, живое олицетворение Прави в Яви. Они светлы, словно само солнце: их волосы мягко струятся и мерцают, даже когда нет ветра, а черты лица прекрасны и безупречны. Ростом они чуть выше среднего человека, но в их облике чувствуется нечто большее, выходящее за рамки обыденного. Боги наделили их великими силами, но ровно настолько, насколько это необходимо для исполнения их миссии. Они редко задерживаются надолго в одном месте, ибо их путь — это служение, а их появление всегда знамение и испытание. Кто-то видит в них спасителей, кто-то — еретиков, но сами Аасимары редко ищут славы. Они инструменты божественной воли, и их выбор, остаться в мире или вернуться в Правь, когда цель будет достигнута, определяет судьбы целых народов."
