        "text": "Внешность:\nЧуть выше среднего роста людей. Волосы мягко струятся и мерцают даже без ветра. Черты лица — идеально правильные, прекрасные. Кожа светится лёгким светом (особенно в темноте). Глаза — яркие, часто цвета неба или пламени."
