        "text": "Активно (1/день): Вы можете потратить 4 благодать, чтобы наложить состояние Успокоение на одного агрессивного гуманоида в пределах даль без проверки навыка (обычное заклинание требует проверки). Это не боевое действие, а акт миротворчества."
