        "kind": "paragraph",
        "text": "Слабые стороны: Холодна и отстранённая. Видит смерть как «бухгалтерию душ», игнорируя горе живых. Её справедливость безжалостна, лишена милосердия. Уязвима перед некромантией, нарушающей естественный ход смерти против её воли."
