        "text": "Ответ бога никогда не бывает прямым и громогласным. Боги не ходят по Яви, как люди. Их ответ — в знаках, совпадениях, внезапных мыслях и чувствах. Вспыхнувшая искра в очаге, внезапно стихший ветер вовремя, нежданная удача или, наоборот, череда мелких неудач, заставляющая задуматься — всё это голоса Прави."
