        "kind": "paragraph",
        "text": "Механика для игроков: Любой персонаж может совершить простое обращение к богу. Это не требует траты ресурсов и не даёт гарантированного механического эффекта. Сказитель может интерпретировать это как подсказку, изменение обстоятельств или просто атмосферную деталь. В критический момент игрок может попросить знамения, и Сказитель тайно бросает к100. Результат близкий к 1 может означать благоприятный знак (например, внезапное озарение, противник спотыкается), результат близкий к 100 — знак гнева или испытания."
